import gurobipy
from gurobipy import GRB
m = gurobipy.Model()
m.setParam('MIPGap', 1e-06)
records = CSVQA_DATA['logical_records']
item_params = {}
item_category = {}
for rec in records.get('item', []):
    v = rec['values']
    ref = v['item_ref']
    item_params[ref] = {'authorized': int(v['authorized']), 'category': v['category'], 'min_lot': int(v['minimum_lot']), 'max_order': int(v['maximum_order']), 'unit_benefit': int(v['unit_benefit_cents']), 'item_fee': int(v['item_fee_cents'])}
    item_category[ref] = v['category']
category_params = {}
for rec in records.get('category', []):
    v = rec['values']
    cat = v['category']
    category_params[cat] = {'activation_fee': int(v['activation_fee_cents']), 'min_qty': int(v['minimum_quantity']), 'max_qty': int(v['maximum_quantity'])}
bundle_params = {}
for rec in records.get('bundle', []):
    v = rec['values']
    a = v['item_a']
    b = v['item_b']
    bundle_params[a, b] = int(v['bonus_cents'])
incompatible_pairs = []
for rec in records.get('incompatible', []):
    v = rec['values']
    incompatible_pairs.append((v['item_a'], v['item_b']))
requires_pairs = []
for rec in records.get('requires', []):
    v = rec['values']
    requires_pairs.append((v['item_ref'], v['prerequisite_ref']))
usage_amount = {}
for rec in records.get('usage', []):
    v = rec['values']
    key = (v['item_ref'], v['resource'])
    usage_amount[key] = int(v['amount'])
capacity_limit = {}
for rec in records.get('capacity_ledger', []):
    v = rec['values']
    r = v['resource']
    capacity_limit[r] = capacity_limit.get(r, 0) + int(v['amount'])
item_ids = set(item_params.keys())
category_ids = set(category_params.keys())
bundle_keys = list(bundle_params.keys())
resource_ids = set()
for _, r in usage_amount:
    resource_ids.add(r)
for r in capacity_limit:
    resource_ids.add(r)
q = {i: m.addVar(vtype=GRB.INTEGER, name=f'q_{i}') for i in item_ids}
z = {i: m.addVar(vtype=GRB.BINARY, name=f'z_{i}') for i in item_ids}
w = {c: m.addVar(vtype=GRB.BINARY, name=f'w_{c}') for c in category_ids}
b = {k: m.addVar(vtype=GRB.BINARY, name=f'b_{k[0]}_{k[1]}') for k in bundle_keys}
for i in item_ids:
    p = item_params[i]
    m.addConstr(q[i] >= p['min_lot'] * z[i])
    m.addConstr(q[i] <= p['max_order'] * z[i])
    m.addConstr(z[i] <= p['authorized'])
for i in item_ids:
    c = item_category[i]
    m.addConstr(w[c] >= z[i])
for c in category_ids:
    sum_z = gurobipy.quicksum((z[i] for i in item_ids if item_category[i] == c))
    m.addConstr(w[c] <= sum_z)
for c in category_ids:
    sum_q = gurobipy.quicksum((q[i] for i in item_ids if item_category[i] == c))
    p = category_params[c]
    m.addConstr(sum_q >= p['min_qty'] * w[c])
    m.addConstr(sum_q <= p['max_qty'] * w[c])
for a, b_item in incompatible_pairs:
    if a in z and b_item in z:
        m.addConstr(z[a] + z[b_item] <= 1)
for item_ref, prereq_ref in requires_pairs:
    if item_ref in z and prereq_ref in z:
        m.addConstr(z[item_ref] <= z[prereq_ref])
for (a, b_item), bonus in bundle_params.items():
    if a in z and b_item in z:
        b_var = b[a, b_item]
        m.addConstr(b_var <= z[a])
        m.addConstr(b_var <= z[b_item])
        m.addConstr(b_var >= z[a] + z[b_item] - 1)
for r in resource_ids:
    usage_expr = gurobipy.quicksum((usage_amount.get((i, r), 0) * q[i] for i in item_ids))
    m.addConstr(usage_expr <= capacity_limit.get(r, 0))
obj = gurobipy.quicksum((item_params[i]['unit_benefit'] * q[i] for i in item_ids)) - gurobipy.quicksum((item_params[i]['item_fee'] * z[i] for i in item_ids)) - gurobipy.quicksum((category_params[c]['activation_fee'] * w[c] for c in category_ids)) + gurobipy.quicksum((bundle_params[k] * b[k] for k in bundle_keys))
m.setObjective(obj, GRB.MAXIMIZE)
m.optimize()
